<?php require 'admin_guard.php';require 'admin_db.php';$msg='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$rid=trim($_POST['repoID']);$cc=trim($_POST['coursecode']);$name=trim($_POST['name']);$n=max(0,(int)$_POST['content_count']);$s=mysqli_prepare($conn,'SELECT coursecode FROM course WHERE coursecode=?');mysqli_stmt_bind_param($s,'s',$cc);mysqli_stmt_execute($s);$exists=mysqli_fetch_assoc(mysqli_stmt_get_result($s));if(!$exists)$err='Course code does not exist.';else{$s=mysqli_prepare($conn,'SELECT repoID FROM repository WHERE repoID=?');mysqli_stmt_bind_param($s,'s',$rid);mysqli_stmt_execute($s);if(mysqli_fetch_assoc(mysqli_stmt_get_result($s)))$err='Repository ID already exists.';else{ $s=mysqli_prepare($conn,'SELECT repoID FROM repository WHERE coursecode=?');mysqli_stmt_bind_param($s,'s',$cc);mysqli_stmt_execute($s);$has=mysqli_fetch_assoc(mysqli_stmt_get_result($s));if($has && empty($_POST['confirm']))$err='A repository already exists for this course. Tick confirmation to add another.';else{$s=mysqli_prepare($conn,'INSERT INTO repository(repoID,coursecode,name,adminID) VALUES(?,?,?,?)');mysqli_stmt_bind_param($s,'ssss',$rid,$cc,$name,$adminID);if(mysqli_stmt_execute($s)){for($i=1;$i<=$n;$i++){ $res=$rid.'-'.str_pad($i,3,'0',STR_PAD_LEFT);$x=mysqli_prepare($conn,'INSERT INTO resource_uploaded_in_repo(repoID,resourceID,upload_date) VALUES(?,?,CURDATE())');mysqli_stmt_bind_param($x,'ss',$rid,$res);mysqli_stmt_execute($x);} $msg='Repository inserted successfully. Thanks!';}}}}}
$cs=mysqli_query($conn,'SELECT coursecode,name FROM course ORDER BY coursecode');?>
<!doctype html><html><head><title>Add Repository</title><link rel="stylesheet" href="admin_pages.css"></head><body><div class="page"><div class="panel"><h1>Add Repository</h1><?php if($err)echo'<div class="notice">'.htmlspecialchars($err).'</div>';if($msg)echo'<div class="notice">'.htmlspecialchars($msg).'</div>';?><form method="post"><label>Repository ID (unique)</label><input name="repoID" required><label>Course Code</label><select name="coursecode" required><option value="">Select</option><?php while($c=mysqli_fetch_assoc($cs)):?><option value="<?=$c['coursecode']?>"><?=$c['coursecode']?> - <?=htmlspecialchars($c['name'])?></option><?php endwhile;?></select><label>Repository Name</label><input name="name" required><label>Number of content rows</label><input type="number" name="content_count" min="0" value="0"><label><input type="checkbox" name="confirm" value="1"> If a repository already exists for this course, I still want to add another.</label><button>Add</button></form><?php if($msg):?><p><a class="btn" href="admin_dashboard.php">Thanks — Return to Dashboard</a></p><?php endif;?></div></div></body></html>
